<?php require __DIR__ . '/../includes/config.php';require_admin();$id=(int)($_GET['id']??0);$product=$id?$pdo->prepare('SELECT * FROM products WHERE id=?'):null;if($product){$product->execute([$id]);$product=$product->fetch();}else{$product=[];}$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$data=[trim($_POST['name']),trim($_POST['slug']),$_POST['category_id']?:null,trim($_POST['description']),$_POST['price']?:0,$_POST['compare_price']?:null,trim($_POST['image']),trim($_POST['tags']),$_POST['stock']?:0,$_POST['status']];if($id){$s=$pdo->prepare('UPDATE products SET name=?,slug=?,category_id=?,description=?,price=?,compare_price=?,image=?,tags=?,stock=?,status=? WHERE id=?');$s->execute([...$data,$id]);}else{$s=$pdo->prepare('INSERT INTO products (name,slug,category_id,description,price,compare_price,image,tags,stock,status) VALUES (?,?,?,?,?,?,?,?,?,?)');$s->execute($data);}flash('success','Product saved.');redirect('admin/products.php');}$pageTitle=$id?'Edit product':'New product';require __DIR__ . '/../includes/header.php'; ?><div class="admin-shell"><div class="row g-0"><aside class="col-lg-2 admin-side"><div class="eyebrow">Control room</div><h2 class="h4 mt-2">Nexa admin</h2><nav class="mt-4"><a href="index.php">Overview</a><a class="active" href="products.php">Products</a><a href="categories.php">Categories</a><a href="orders.php">Orders</a><a href="users.php">Users</a></nav></aside><section class="col-lg-10 p-4 p-lg-5"><h1 class="h2 mb-4"><?= $id?'Edit product':'New product' ?></h1><form method="post" class="panel row g-3"><div class="col-md-8"><label class="form-label">Product name</label><input required name="name" class="form-control" value="<?= e($product['name']??'') ?>"></div><div class="col-md-4"><label class="form-label">Slug</label><input required name="slug" class="form-control" value="<?= e($product['slug']??'') ?>"></div><div class="col-md-4"><label class="form-label">Category</label><select name="category_id" class="form-select"><option value="">Uncategorised</option><?php foreach($categories as $category): ?><option value="<?= $category['id'] ?>" <?= ($product['category_id']??'')==$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Price</label><input required type="number" step=".01" name="price" class="form-control" value="<?= e((string)($product['price']??'')) ?>"></div><div class="col-md-4"><label class="form-label">Compare price</label><input type="number" step=".01" name="compare_price" class="form-control" value="<?= e((string)($product['compare_price']??'')) ?>"></div><div class="col-md-8"><label class="form-label">Image URL</label><input name="image" class="form-control" value="<?= e($product['image']??'') ?>"></div><div class="col-md-4"><label class="form-label">Stock</label><input type="number" name="stock" class="form-control" value="<?= e((string)($product['stock']??0)) ?>"></div><div class="col-12"><label class="form-label">Tags</label><input name="tags" class="form-control" value="<?= e($product['tags']??'') ?>"></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" rows="4" class="form-control"><?= e($product['description']??'') ?></textarea></div><div class="col-md-4"><label class="form-label">Status</label><select name="status" class="form-select"><option value="active" <?= ($product['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="draft" <?= ($product['status']??'')==='draft'?'selected':'' ?>>Draft</option></select></div><div class="col-12"><button class="btn btn-accent">Save product</button> <a href="products.php" class="btn btn-outline-dark">Cancel</a></div></form></section></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>